cd /home/ubuntu/.agent-ml-research-idea_gen_0520_2/projects/irt_equated_bench_regen && python3 -c "
# Look for phi specifically relating to contamination labels
# Search in md files more specifically
import os
for dirpath, dirs, files in os.walk('artifacts'):
    for f in files:
        if f.endswith('.md'):
            path = os.path.join(dirpath, f)
            try:
                with open(path) as fh:
                    lines = fh.readlines()
                for i, line in enumerate(lines):
                    if '0.012' in line or ('phi' in line.lower() and ('contamin' in line.lower() or 'li_' in line.lower() or 'overlap' in line.lower())):
                        print(f'{path}:{i+1}: {line.rstrip()}')
            except:
                pass
" 2>/dev/null | head -30

